import { useLayoutEffect, useRef, useState } from 'react'
import { gsap, ScrollTrigger } from '../lib/motion.js'
import { MAKING, GLAZES } from '../data.js'

// The firing curve. One authored progress value drives the drawn curve, the
// temperature readout, the heat in the kiln photograph, and which of the three
// pieces has come out of the firing.
const Y0 = 420
const TOP = 1300
const y = (t) => Y0 - (t / TOP) * 360

// Firing one (bisque to 1000°C), the glazing gap, then firing two: fourteen
// hours up to 1260°C and a four hour hold.
const PATH = [
  `M 60 ${y(20)}`,
  `C 150 ${y(20)} 190 ${y(620)} 260 ${y(1000)}`,
  `L 300 ${y(1000)}`,
  `C 340 ${y(1000)} 380 ${y(240)} 420 ${y(40)}`,
].join(' ')

const PATH2 = [
  `M 520 ${y(40)}`,
  `C 640 ${y(120)} 780 ${y(900)} 900 ${y(1260)}`,
  `L 1030 ${y(1260)}`,
  `C 1080 ${y(1260)} 1120 ${y(700)} 1160 ${y(360)}`,
].join(' ')

export default function Firing({ reduced, glaze }) {
  const root = useRef(null)
  const p1 = useRef(null)
  const p2 = useRef(null)
  const [readout, setReadout] = useState({ temp: 20, stage: 'The kiln is cold' })
  const [heat, setHeat] = useState(0)

  useLayoutEffect(() => {
    const el = root.current
    const a = p1.current
    const b = p2.current
    const la = a.getTotalLength()
    const lb = b.getTotalLength()
    gsap.set([a, b], { strokeDasharray: (i) => (i === 0 ? la : lb) })

    const apply = (prog) => {
      // two curves share one progress value: 0-0.42 is the bisque firing,
      // 0.42-0.5 the glazing gap, 0.5-1 the glaze firing.
      const pa = gsap.utils.clamp(0, 1, prog / 0.42)
      const pb = gsap.utils.clamp(0, 1, (prog - 0.5) / 0.5)
      gsap.set(a, { strokeDashoffset: la * (1 - pa) })
      gsap.set(b, { strokeDashoffset: lb * (1 - pb) })
      const active = pb > 0 ? b : a
      const len = pb > 0 ? lb * pb : la * pa
      const pt = active.getPointAtLength(Math.max(len, 0.01))
      const temp = Math.max(20, Math.round(((Y0 - pt.y) / 360) * TOP))
      let stage = 'The kiln is cold'
      if (prog > 0.02 && prog < 0.30) stage = 'First firing — bisque'
      else if (prog >= 0.30 && prog < 0.42) stage = 'Cooling'
      else if (prog >= 0.42 && prog < 0.5) stage = 'Glazed by hand'
      else if (prog >= 0.5 && prog < 0.80) stage = 'Second firing — fourteen hours up'
      else if (prog >= 0.80 && prog < 0.92) stage = 'Four hour hold'
      else if (prog >= 0.92) stage = 'Cooling — two days before it is opened'
      setReadout({ temp: prog < 0.02 ? 20 : temp, stage })
      setHeat(gsap.utils.clamp(0, 1, temp / 1260))
    }

    if (reduced) {
      apply(0.86)
      el.querySelectorAll('[data-beat]').forEach((n) => n.setAttribute('data-on', ''))
      return
    }

    const ctx = gsap.context(() => {
      ScrollTrigger.create({
        trigger: el,
        start: 'top top',
        end: 'bottom bottom',
        pin: el.querySelector('.firing__stage'),
        pinSpacing: false,
        scrub: true,
        onUpdate: (self) => apply(self.progress),
        onRefreshInit: () => apply(0),
      })
      el.querySelectorAll('[data-beat]').forEach((node) => {
        ScrollTrigger.create({
          trigger: node,
          start: 'top 78%',
          onEnter: () => node.setAttribute('data-on', ''),
          onLeaveBack: () => node.removeAttribute('data-on'),
        })
      })
    }, el)
    return () => ctx.revert()
  }, [reduced])

  return (
    <section className="firing" id="making" ref={root} aria-labelledby="firing-h">
      <div className="firing__stage">
        <img className="firing__kiln" src="/media/kiln.webp" alt="Flame inside the firebox of a kiln" />
        <div className="firing__heat" style={{ opacity: 0.15 + heat * 0.85, transform: `scale(${1 + heat * 0.5})` }} />
        <div className="firing__grid">
