            <ul>
              {both.map((p) => (
                <li key={p.id}>{p.name}</li>
              ))}
            </ul>
            <p className="care__colnote">{CARE[2]}</p>
          </div>
          <div className="care__col care__col--no">
            <p className="care__colhead">Neither</p>
            <ul>
              {neither.map((p) => (
                <li key={p.id}>{p.name}</li>
              ))}
            </ul>
            <p className="care__colnote">{CARE[1]}</p>
          </div>
        </div>
      </div>
    </section>
  )
}

function Notes() {
  return (
    <section className="notes" aria-labelledby="notes-h">
      <h2 className="visually-hidden" id="notes-h">What two buyers said</h2>
      {NOTES.map((n) => {
        const p = productById(n.piece)
        return (
          <figure className="note" key={n.name} data-reveal>
            <img className="note__img" src={`/media/${n.img}.webp`} alt={`Detail of a ${p.name}`} loading="lazy" />
            <blockquote className="note__quote">{n.quote}</blockquote>
            <figcaption className="note__by">
              <span className="note__name">{n.name}</span>
              <span className="note__bought">{n.bought}</span>
              <a className="note__link" href={`#piece-${p.id}`}>
                See the {p.name} &mdash; &pound;{p.price}
              </a>
            </figcaption>
          </figure>
        )
      })}
    </section>
  )
}

function Shipping() {
  return (
    <section className="ship" aria-labelledby="ship-h">
      <h2 id="ship-h">Getting it to you</h2>
      <ol className="ship__list">
        {SHIPPING.map((line, i) => (
          <li key={i} data-reveal>
            <span className="ship__n" aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>
            {line}
          </li>
        ))}
      </ol>
    </section>
  )
}

function Bag({ bag, remove, total, open, setOpen }) {
  const panel = useRef(null)
  useEffect(() => {
    if (!open) return
    const onKey = (e) => e.key === 'Escape' && setOpen(false)
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [open, setOpen])

  const count = bag.reduce((n, l) => n + l.qty, 0)
  const toFree = 60 - total

  return (
    <>
      <div className={`bag ${open ? 'is-open' : ''}`} role="dialog" aria-label="Your bag" ref={panel}>
        <div className="bag__head">
          <h2>Bag</h2>
          <button type="button" className="bag__close" onClick={() => setOpen(false)}>
            Close
          </button>
        </div>
        {bag.length === 0 && <p className="bag__empty">Nothing in the bag yet.</p>}
        <ul className="bag__lines">
          {bag.map((l, i) => (
            <li key={`${l.id}-${l.glaze}`} className="bagline">
              <img src={`/media/${productById(l.id).img}.webp`} alt="" />
              <div className="bagline__body">
                <p className="bagline__name">
                  {l.name} <span className={`bagline__glaze bagline__glaze--${l.glaze}`}>{glazeName(l.glaze)}</span>
                </p>
                <p className="bagline__sum">
                  {l.qty} &times; &pound;{l.price} = <strong>&pound;{l.price * l.qty}</strong>
                </p>
              </div>
              <button type="button" className="bagline__rm" onClick={() => remove(i)}>
                Remove<span className="visually-hidden"> {l.name} in {glazeName(l.glaze)}</span>
              </button>
            </li>
          ))}
        </ul>
        {bag.length > 0 && (
          <div className="bag__foot">
            <p className="bag__total">
              <span>Total</span>
              <span>&pound;{total}</span>
            </p>
            <p className="bag__ship">
              {toFree > 0
                ? `£${toFree} more and the shipping is free.`
                : 'Shipping is free — you are over £60.'}
            </p>
          </div>
        )}
      </div>
      <button
        type="button"
        className={`bagbar ${count ? 'has-items' : ''}`}
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <span className="bagbar__label">Bag</span>
        <span className="bagbar__count">{count}</span>
        <span className="bagbar__total">&pound;{total}</span>
      </button>
      <div className={`scrim ${open ? 'is-on' : ''}`} onClick={() => setOpen(false)} aria-hidden="true" />
    </>
  )
}

export default function App() {
  const [bag, setBag] = useState([])
  const [glaze, setGlaze] = useState('ash')
  const [open, setOpen] = useState(false)
  const reduced = useReducedMotion()
  useReveal(reduced)

  useEffect(() => {
    document.documentElement.dataset.glaze = glaze
  }, [glaze])

  useEffect(() => {
    const t = setTimeout(() => ScrollTrigger.refresh(), 500)
    return () => clearTimeout(t)
  }, [])

  function add(product, glazeId) {
    if (product.stock === 'out') return
    setBag((lines) => {
      const at = lines.findIndex((l) => l.id === product.id && l.glaze === glazeId)
      if (at === -1)
        return [...lines, { id: product.id, name: product.name, glaze: glazeId, price: product.price, qty: 1 }]
      const next = lines.slice()
      next[at] = { ...next[at], qty: next[at].qty + 1 }
      return next
    })
  }

  function remove(index) {
    setBag((lines) => lines.filter((_, i) => i !== index))
  }

  const total = bag.reduce((sum, l) => sum + l.price * l.qty, 0)
  const count = bag.reduce((n, l) => n + l.qty, 0)

  return (
    <div className="page">
      <a className="skip" href="#shop">Skip to the nine pieces</a>
      <header className="top">
        <a className="top__mark" href="#top">Kilnwork</a>
        <nav className="top__nav">
          <a href="#shop">Shop</a>
          <a href="#glazes">Glazes</a>
          <a href="#making">Making</a>
          <a href="#care">Care</a>
        </nav>
        <button type="button" className="top__bag" onClick={() => setOpen(true)} aria-expanded={open}>
          Bag <span className="top__count">{count}</span>
        </button>
      </header>

      <main id="top">
        <Hero glaze={glaze} setGlaze={setGlaze} reduced={reduced} />
        <Fires glaze={glaze} setGlaze={setGlaze} />
        <Shelf glaze={glaze} setGlaze={setGlaze} add={add} bagCount={count} />
        <Firing reduced={reduced} glaze={glaze} />
        <Care />
        <Notes />
        <Shipping />
      </main>

      <footer className="foot">
        <p className="foot__line">{MAKING[0]}</p>
        <div className="foot__credits">
          <p className="foot__creditshead">Photographs</p>
          <dl>
            {CREDITS.map(([what, who]) => (
              <div key={what}>
                <dt>{what}</dt>
                <dd>{who}</dd>
              </div>
            ))}
          </dl>
        </div>
      </footer>

      <Bag bag={bag} remove={remove} total={total} open={open} setOpen={setOpen} />
    </div>
  )
}

@font-face {
  font-family: 'Fraunces';
  src: url('/fonts/fraunces-normal.woff2') format('woff2-variations');
  font-weight: 300 700;
  font-display: swap;
}
@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter-normal.woff2') format('woff2-variations');
  font-weight: 300 700;
  font-display: swap;
}

:root {
  --paper: #f0e9de;
  --paper-2: #e5dccd;
  --paper-3: #d8cdba;
  --ink: #1d1712;
  --ink-2: #574c41;
  --ink-3: #857868;
  --kiln: #16100c;
  --ash: #8fa189;
  --iron: #9d4a26;
  --salt: #cbbfa6;
  --glaze: var(--ash);
  --glaze-ink: #3d4a39;
  --rule: rgba(29, 23, 18, 0.18);
  --serif: 'Fraunces', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', system-ui, -apple-system, sans-serif;
  --pad: clamp(1.25rem, 5vw, 5.5rem);
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  --t: 150ms;
}
html[data-glaze='iron'] {
  --glaze: var(--iron);
  --glaze-ink: #6d2f14;
}
html[data-glaze='salt'] {
  --glaze: var(--salt);
  --glaze-ink: #6b5c40;
}

* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 5rem;
}
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: clamp(1rem, 0.96rem + 0.2vw, 1.0625rem);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
img {
  max-width: 100%;
  display: block;
}
h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 400;
  font-variation-settings: 'SOFT' 20, 'WONK' 1;
  letter-spacing: -0.015em;
  line-height: 1.04;
  margin: 0;
  text-wrap: balance;
}
p {
  margin: 0 0 1em;
  text-wrap: pretty;
}
a {
  color: inherit;
}
button {
  font: inherit;
  color: inherit;
}
:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
  border-radius: 1px;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.skip {
  position: absolute;
  left: -999px;
  top: 0;
  z-index: 200;
  background: var(--ink);
  color: var(--paper);
  padding: 0.75rem 1rem;
}
.skip:focus {
  left: 0;
}

.eyebrow {
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin-bottom: 0.9rem;
}

/* ---------- entrance grammar (one for the whole route) ---------- */
[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 520ms var(--ease), transform 520ms var(--ease);
}
[data-reveal][data-revealed] {
  opacity: 1;
  transform: none;
}
.shelf__row [data-reveal] {
  transition-delay: calc(var(--i, 0) * 45ms);
}

/* ---------- header ---------- */
.top {
  position: sticky;
  top: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 0.7rem var(--pad);
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--rule);
}
.top__mark {
  font-family: var(--serif);
  font-size: 1.2rem;
  letter-spacing: 0.01em;
  text-decoration: none;
  margin-right: auto;
}
.top__nav {
  display: flex;
  gap: 1.4rem;
  font-size: 0.85rem;
}
.top__nav a {
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: border-color var(--t) var(--ease), color var(--t) var(--ease);
}
.top__nav a:hover {
  border-color: var(--ink);
}
.top__bag,
.bagline__rm,
.bag__close,
.hero__jump {
  background: none;
  border: 0;
  cursor: pointer;
}
.top__bag {
  font-size: 0.85rem;
  border: 1px solid var(--rule);
  border-radius: 999px;
  padding: 0.35rem 0.85rem;
  transition: background var(--t) var(--ease), border-color var(--t) var(--ease);
}
.top__bag:hover {
  background: var(--paper-2);
  border-color: var(--ink);
}
.top__count {
  display: inline-block;
  min-width: 1.35em;
  text-align: center;
  margin-left: 0.2rem;
  color: var(--ink-2);
}

/* ---------- hero ---------- */
.hero {
  position: relative;
  min-height: calc(100svh - 3.4rem);
  display: grid;
  grid-template-columns: 1fr min(46%, 640px);
  align-items: stretch;
  background: var(--kiln);
  color: #efe6d9;
  overflow: hidden;
}
.hero__media {
  grid-column: 2;
  overflow: hidden;
  position: relative;
}
.hero__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  will-change: transform;
}
.hero__media::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--kiln) 0%, rgba(22, 16, 12, 0.25) 32%, transparent 60%);
}
.hero__text {
  grid-column: 1;
  align-self: center;
  padding: clamp(3rem, 8vh, 7rem) 0 clamp(3rem, 8vh, 7rem) var(--pad);
  padding-right: clamp(1rem, 4vw, 4rem);
  max-width: 42rem;
}
.hero .eyebrow {
  color: #a9998a;
}
.hero h1 {
  font-size: clamp(2.7rem, 7.2vw, 5.6rem);
  font-variation-settings: 'SOFT' 30, 'WONK' 1, 'opsz' 120;
  margin-bottom: 1.4rem;
}
.hero h1 em {
  font-style: italic;
  color: var(--glaze);
  transition: color 400ms var(--ease);
}
.hero__lede {
  font-size: clamp(1rem, 0.95rem + 0.35vw, 1.2rem);
  color: #c4b7a8;
  max-width: 34rem;
  margin-bottom: 2.2rem;
}
.hero__picklabel {
  display: block;
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9a8b7d;
  margin-bottom: 0.7rem;
}
.hero__jump {
  display: inline-block;
  margin-top: 2.4rem;
  font-size: 0.9rem;
  text-decoration: none;
  border-bottom: 1px solid rgba(239, 230, 217, 0.4);
  padding-bottom: 3px;
  transition: border-color var(--t) var(--ease), transform var(--t) var(--ease);
}
.hero__jump:hover {
  border-color: var(--glaze);
  transform: translateY(2px);
}

/* ---------- glaze chips ---------- */
.chips {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.chip {
  --c: var(--ash);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.45rem 0.95rem 0.45rem 0.7rem;
  border: 1px solid currentColor;
  border-radius: 999px;
  background: none;
  cursor: pointer;
  font-size: 0.85rem;
  color: inherit;
  opacity: 0.62;
  transition: opacity var(--t) var(--ease), background var(--t) var(--ease), transform var(--t) var(--ease);
}
.chip::before {
  content: '';
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  background: var(--c);
}
.chip--ash {
  --c: var(--ash);
}
.chip--iron {
  --c: var(--iron);
}
.chip--salt {
  --c: var(--salt);
}
.chip:hover {
  opacity: 0.9;
}
.chip:active {
  transform: scale(0.97);
}
.chip.is-on {
  opacity: 1;
  background: color-mix(in srgb, var(--c) 22%, transparent);
  border-color: var(--c);
}

/* ---------- the three fires ---------- */
.fires {
  padding: clamp(4rem, 10vh, 8rem) var(--pad) clamp(3rem, 7vh, 6rem);
  background: linear-gradient(var(--kiln) 0 6rem, var(--paper) 6rem);
}
.fires__head {
  max-width: 46rem;
  margin-bottom: clamp(2rem, 5vh, 3.5rem);
}
.fires__head h2 {
  font-size: clamp(1.7rem, 3.4vw, 2.9rem);
  margin-bottom: 1rem;
}
.fires__lede {
  color: var(--ink-2);
  max-width: 34rem;
}
.fires__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.75rem, 1.6vw, 1.6rem);
}
.fire__btn {
  display: block;
  width: 100%;
  text-align: left;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}
.fire__media {
  display: block;
  overflow: hidden;
  background: var(--paper-2);
  aspect-ratio: 4 / 5;
}
.fire__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.85) contrast(1.02);
  transition: transform 600ms var(--ease), filter 400ms var(--ease);
}
.fire__btn:hover .fire__media img {
  transform: scale(1.035);
}
.fire.is-on .fire__media img {
  filter: none;
}
.fire__body {
  display: block;
  padding-top: 1rem;
  border-top: 2px solid var(--rule);
  margin-top: 1rem;
  transition: border-color 300ms var(--ease);
}
.fire.is-on .fire__body {
  border-color: var(--c, var(--glaze));
}
.fire--ash {
  --c: var(--ash);
}
.fire--iron {
  --c: var(--iron);
}
.fire--salt {
  --c: #b3a17f;
}
.fire__name {
  display: block;
  font-family: var(--serif);
  font-size: clamp(1.3rem, 2vw, 1.8rem);
  margin-bottom: 0.35rem;
}
.fire__note {
  display: block;
  color: var(--ink-2);
  margin-bottom: 0.6rem;
  max-width: 26rem;
}
.fire__count {
  display: block;
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.fire.is-on .fire__count {
  color: var(--c);
}

/* ---------- the shelf ---------- */
.shop {
  padding: clamp(3.5rem, 9vh, 7rem) var(--pad) clamp(4rem, 10vh, 8rem);
  background: var(--paper);
  border-top: 1px solid var(--rule);
}
.shop__head {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: clamp(1.5rem, 4vw, 4rem);
  align-items: end;
  margin-bottom: 2rem;
}
.shop__head h2 {
  font-size: clamp(2rem, 4.6vw, 3.6rem);
}
.shop__em {
  font-style: italic;
  color: var(--glaze-ink);
}
.shop__note {
  color: var(--ink-2);
  max-width: 30rem;
  margin: 0;
}
.shop__filter {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 0.9rem 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  margin-bottom: clamp(2rem, 5vh, 3.5rem);
  position: sticky;
  top: 3.3rem;
  background: color-mix(in srgb, var(--paper) 92%, transparent);
  backdrop-filter: blur(6px);
  z-index: 40;
}
.shop__filterlabel {
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.shop__filternote {
  margin: 0;
  font-size: 0.85rem;
  color: var(--ink-2);
}
.shelf {
  margin-bottom: clamp(2.5rem, 6vh, 4.5rem);
}
.shelf__row {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: flex-end;
  gap: clamp(0.75rem, 1.8vw, 2rem);
}
.piece {
  flex-grow: 0;
  flex-shrink: 1;
  min-width: 0;
  transition: opacity 300ms var(--ease);
}
.piece__frame {
  position: relative;
  aspect-ratio: 1;
  overflow: hidden;
  background: var(--paper-2);
  outline: 1px solid transparent;
  transition: outline-color var(--t) var(--ease), transform var(--t) var(--ease);
}
.piece__frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 700ms var(--ease), filter 400ms var(--ease);
}
.piece:hover .piece__frame img {
  transform: scale(1.04);
}
.piece:hover .piece__frame {
  outline-color: var(--glaze);
}
.piece.is-out .piece__frame img {
  filter: grayscale(0.65) brightness(1.04);
}
.piece.is-other .piece__frame img {
  filter: grayscale(0.5) opacity(0.72);
}
.piece__sold {
  position: absolute;
  left: 0;
  bottom: 0;
  background: var(--ink);
  color: var(--paper);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.3rem 0.6rem;
}
.piece__body {
  padding-top: 0.75rem;
}
.piece__name {
  font-size: clamp(1rem, 1.25vw, 1.3rem);
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  align-items: baseline;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.35rem;
  margin-bottom: 0.4rem;
}
.piece__price {
  font-family: var(--sans);
  font-size: 0.9rem;
  color: var(--ink-2);
}
.piece__spec,
.piece__care,
.piece__stock,
.piece__not {
  margin: 0 0 0.25rem;
  font-size: 0.78rem;
  color: var(--ink-2);
  line-height: 1.45;
}
.piece__stock {
  color: var(--glaze-ink);
}
.piece__stock.is-out {
  color: #8a5a3a;
}
.piece__care {
  color: var(--ink-3);
}
.piece__not {
  color: var(--ink-3);
  font-style: italic;
  margin-top: 0.4rem;
}
.piece__buy {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.7rem;
}
.buy {
  --c: var(--ash);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  padding: 0.35rem 0.7rem;
  border: 1px solid var(--rule);
  background: none;
  cursor: pointer;
  border-radius: 999px;
  transition: background var(--t) var(--ease), border-color var(--t) var(--ease), transform var(--t) var(--ease),
    color var(--t) var(--ease);
}
.buy--ash {
  --c: var(--ash);
}
.buy--iron {
  --c: var(--iron);
}
.buy--salt {
  --c: #b3a17f;
}
.buy__dot {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: var(--c);
}
.buy:hover:not(:disabled) {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
.buy:active:not(:disabled) {
  transform: scale(0.97);
}
.buy.is-current {
  border-color: var(--c);
}
.buy:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.rule {
  position: relative;
  height: 2.1rem;
  margin-top: 0.9rem;
  border-top: 1px solid var(--ink-3);
}
.rule__tick {
  position: absolute;
  top: 0;
  width: 1px;
  height: 5px;
  background: var(--ink-3);
}
.rule__tick.is-major {
  height: 9px;
}
.rule__tick i {
  position: absolute;
  top: 11px;
  left: 0;
  transform: translateX(-50%);
  font-style: normal;
  font-size: 0.65rem;
  color: var(--ink-3);
  letter-spacing: 0.06em;
}
.rule__unit {
  position: absolute;
  right: 0;
  top: 10px;
  font-size: 0.65rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.shop__bagline {
  margin: 0;
  font-size: 0.85rem;
  color: var(--ink-2);
}

/* ---------- the firing ---------- */
.firing {
  position: relative;
  background: var(--kiln);
  color: #eadfd0;
}
.firing__stage {
  position: relative;
  height: 100svh;
  overflow: hidden;
}
.firing__kiln {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.42;
  filter: contrast(1.05) saturate(0.9);
}
.firing__heat {
  position: absolute;
  left: 22%;
  top: 55%;
  width: 60vmax;
  height: 60vmax;
  transform-origin: center;
  translate: -50% -50%;
  background: radial-gradient(circle, rgba(255, 138, 40, 0.55), rgba(255, 90, 20, 0.16) 42%, transparent 68%);
  pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 120ms linear;
}
.firing__grid {
  position: relative;
  height: 100%;
  display: grid;
  grid-template-rows: auto 1fr;
  padding: clamp(2rem, 6vh, 4rem) var(--pad);
  gap: 1rem;
}
.firing__head {
  max-width: 34rem;
}
.firing .eyebrow {
  color: #9b8672;
}
.firing__head h2 {
  font-size: clamp(1.8rem, 3.6vw, 3rem);
}
.firing__readout {
  position: absolute;
  right: var(--pad);
  top: clamp(2rem, 6vh, 4rem);
  text-align: right;
}
.firing__temp {
  display: block;
  font-family: var(--serif);
  font-size: clamp(3rem, 8vw, 7rem);
  line-height: 0.9;
  color: #ffb166;
  font-variant-numeric: tabular-nums;
}
.firing__deg {
  font-size: 0.4em;
  margin-left: 0.1em;
  color: #c98a4e;
}
.firing__stagename {
  display: block;
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #b09883;
  margin-top: 0.5rem;
}
.firing__chart {
  align-self: end;
  width: 100%;
  height: auto;
  max-height: 56vh;
  overflow: visible;
}
.firing__ghost {
  fill: none;
  stroke: rgba(234, 223, 208, 0.16);
  stroke-width: 2;
  stroke-dasharray: 3 6;
}
.firing__line {
  fill: none;
  stroke: #ffa54f;
  stroke-width: 3.5;
  stroke-linecap: round;
  filter: drop-shadow(0 0 12px rgba(255, 140, 50, 0.55));
}
.firing__axis line {
  stroke: rgba(234, 223, 208, 0.14);
  stroke-width: 1;
}
.firing__axis text,
.firing__marks text {
  fill: #b09883;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  letter-spacing: 0.04em;
}
.firing__marks text {
  fill: #e0cdb4;
}
.firing__gap {
  stroke: rgba(234, 223, 208, 0.4);
  stroke-width: 1.5;
  stroke-dasharray: 2 5;
}
.firing__beats {
  position: relative;
  z-index: 2;
  padding: 0 var(--pad) clamp(4rem, 10vh, 8rem);
  max-width: 62rem;
  margin-inline: auto;
}
.firing__beat {
  font-family: var(--serif);
  font-size: clamp(1.25rem, 2.4vw, 2rem);
  line-height: 1.3;
  color: #e7dbc9;
  margin: 0 0 clamp(4rem, 22vh, 14rem);
  max-width: 30rem;
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 700ms var(--ease), transform 700ms var(--ease);
}
.firing__beat:nth-child(2) {
  margin-left: auto;
}
.firing__beat[data-on] {
  opacity: 1;
  transform: none;
}
.firing__out,
.firing__restock {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 700ms var(--ease), transform 700ms var(--ease);
}
.firing__out[data-on],
.firing__restock[data-on] {
  opacity: 1;
  transform: none;
}
.firing__outlead {
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #b09883;
  margin-bottom: 1.2rem;
}
.firing__trio {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.75rem, 2vw, 1.75rem);
  padding: 0;
  margin: 0 0 clamp(4rem, 14vh, 9rem);
}
.firing__trio li {
  position: relative;
}
.firing__trio img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  filter: brightness(0.7) saturate(0.7);
  transition: filter 500ms var(--ease);
}
.firing__trio li.is-chosen img {
  filter: none;
  outline: 1px solid var(--glaze);
  outline-offset: 4px;
}
.firing__trio span {
  display: block;
  margin-top: 0.6rem;
  font-size: 0.85rem;
  color: #b09883;
}
.firing__trio li.is-chosen span {
  color: #f0e2cd;
}
.firing__restock {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1.25rem, 4vw, 3rem);
  align-items: center;
}
.firing__restock img {
  width: 100%;
  aspect-ratio: 3 / 2;
  object-fit: cover;
}
.firing__restock p {
  font-family: var(--serif);
  font-size: clamp(1.1rem, 1.8vw, 1.5rem);
  line-height: 1.35;
  color: #e7dbc9;
  margin: 0;
}

/* ---------- care ---------- */
.care {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(1.5rem, 5vw, 5rem);
  align-items: center;
  padding: clamp(4rem, 10vh, 8rem) var(--pad);
  background: var(--paper-2);
}
.care__fig {
  margin: 0;
  position: relative;
}
.care__fig img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
}
.care__anno {
  position: absolute;
  left: 8%;
  bottom: -1.5rem;
  background: var(--paper);
  padding: 0.7rem 0.9rem;
  max-width: 20rem;
  font-size: 0.82rem;
  line-height: 1.4;
  border-left: 2px solid var(--ink);
}
.care__annoline {
  position: absolute;
  left: -1px;
  bottom: 100%;
  width: 1px;
  height: 3.5rem;
  background: var(--ink);
}
.care__body h2 {
  font-size: clamp(1.9rem, 4vw, 3.2rem);
  margin-bottom: 1.2rem;
}
.care__lead {
  font-size: clamp(1.05rem, 1.4vw, 1.25rem);
  color: var(--ink-2);
  max-width: 34rem;
  margin-bottom: 2rem;
}
.care__split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1rem, 3vw, 2.5rem);
  border-top: 1px solid var(--rule);
  padding-top: 1.25rem;
}
.care__colhead {
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin-bottom: 0.7rem;
}
.care__col ul {
  list-style: none;
  margin: 0 0 0.9rem;
  padding: 0;
  font-family: var(--serif);
  font-size: 1.05rem;
  line-height: 1.6;
}
.care__col--no ul li {
  text-decoration: line-through;
  text-decoration-color: var(--iron);
  text-decoration-thickness: 1px;
}
.care__colnote {
  font-size: 0.82rem;
  color: var(--ink-2);
  margin: 0;
}

/* ---------- notes ---------- */
.notes {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1.5rem, 5vw, 5rem);
  padding: clamp(4rem, 10vh, 7rem) var(--pad);
}
.note {
  margin: 0;
  display: grid;
  grid-template-columns: minmax(0, 7rem) 1fr;
  gap: clamp(1rem, 2vw, 1.75rem);
  align-items: start;
}
.note__img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 50%;
}
.note__quote {
  margin: 0 0 1rem;
  font-family: var(--serif);
  font-size: clamp(1.05rem, 1.6vw, 1.35rem);
  line-height: 1.4;
  text-indent: -0.4em;
}
.note__quote::before {
  content: '\201C';
}
.note__quote::after {
  content: '\201D';
}
.note__by {
  font-size: 0.85rem;
  color: var(--ink-2);
}
.note__name {
  display: block;
  color: var(--ink);
}
.note__bought {
  display: block;
  margin-bottom: 0.5rem;
}
.note__link {
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 2px;
  transition: border-color var(--t) var(--ease);
}
.note__link:hover {
  border-color: var(--ink);
}

/* ---------- shipping ---------- */
.ship {
  padding: clamp(3rem, 8vh, 6rem) var(--pad) clamp(4rem, 9vh, 7rem);
  border-top: 1px solid var(--rule);
}
.ship h2 {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  margin-bottom: 2rem;
}
.ship__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1.25rem, 3vw, 3rem);
}
.ship__list li {
  font-family: var(--serif);
  font-size: clamp(1.05rem, 1.5vw, 1.3rem);
  line-height: 1.35;
  border-top: 2px solid var(--ink);
  padding-top: 0.9rem;
}
.ship__n {
  display: block;
  font-family: var(--sans);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  color: var(--ink-3);
  margin-bottom: 0.6rem;
}

/* ---------- footer ---------- */
.foot {
  background: var(--kiln);
  color: #cbbca9;
  padding: clamp(3rem, 7vh, 5rem) var(--pad) 7rem;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: clamp(1.5rem, 5vw, 5rem);
}
.foot__line {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2vw, 1.7rem);
  line-height: 1.35;
  color: #eadfd0;
  max-width: 26rem;
  margin: 0;
}
.foot__creditshead {
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #8b7a68;
  margin-bottom: 0.9rem;
}
.foot__credits dl {
  margin: 0;
  font-size: 0.78rem;
  line-height: 1.5;
}
.foot__credits div {
  display: grid;
  grid-template-columns: 11rem 1fr;
  gap: 0.75rem;
  padding: 0.35rem 0;
  border-top: 1px solid rgba(234, 223, 208, 0.12);
}
.foot__credits dt {
  color: #8b7a68;
}
.foot__credits dd {
  margin: 0;
}

/* ---------- bag ---------- */
.bagbar {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 80;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.7rem 1.1rem;
  border: 0;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  cursor: pointer;
  font-size: 0.9rem;
  box-shadow: 0 6px 24px rgba(29, 23, 18, 0.28);
  transition: transform var(--t) var(--ease), background var(--t) var(--ease);
}
.bagbar:hover {
  transform: translateY(-2px);
}
.bagbar:active {
  transform: scale(0.98);
}
.bagbar__count {
  min-width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--glaze);
  color: var(--kiln);
  font-size: 0.8rem;
}
.bagbar__total {
  color: #b3a696;
}
.bag {
  position: fixed;
  top: 0;
  right: 0;
  z-index: 90;
  width: min(26rem, 92vw);
  height: 100svh;
  background: var(--paper);
  border-left: 1px solid var(--rule);
  transform: translateX(101%);
  transition: transform 420ms var(--ease);
  display: flex;
  flex-direction: column;
  padding: 1.25rem;
  overflow-y: auto;
  box-shadow: -20px 0 50px rgba(29, 23, 18, 0.14);
}
.bag.is-open {
  transform: none;
}
.bag__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.75rem;
  margin-bottom: 1rem;
}
.bag__head h2 {
  font-size: 1.6rem;
}
.bag__close {
  font-size: 0.82rem;
  border-bottom: 1px solid var(--rule);
  transition: border-color var(--t) var(--ease);
}
.bag__close:hover {
  border-color: var(--ink);
}
.bag__empty {
  color: var(--ink-2);
}
.bag__lines {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
}
.bagline {
  display: grid;
  grid-template-columns: 3.25rem 1fr auto;
  gap: 0.75rem;
  align-items: start;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--rule);
}
.bagline img {
  width: 3.25rem;
  height: 3.25rem;
  object-fit: cover;
}
.bagline__name {
  margin: 0 0 0.2rem;
  font-family: var(--serif);
  font-size: 1.05rem;
}
.bagline__glaze {
  font-family: var(--sans);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  background: var(--paper-3);
  color: var(--ink-2);
  vertical-align: 2px;
}
.bagline__glaze--ash {
  background: color-mix(in srgb, var(--ash) 45%, var(--paper));
}
.bagline__glaze--iron {
  background: color-mix(in srgb, var(--iron) 30%, var(--paper));
}
.bagline__glaze--salt {
  background: color-mix(in srgb, var(--salt) 60%, var(--paper));
}
.bagline__sum {
  margin: 0;
  font-size: 0.85rem;
  color: var(--ink-2);
}
.bagline__rm {
  font-size: 0.75rem;
  color: var(--ink-3);
  border-bottom: 1px solid transparent;
  transition: color var(--t) var(--ease), border-color var(--t) var(--ease);
}
.bagline__rm:hover {
  color: var(--ink);
  border-color: var(--ink);
}
.bag__foot {
  padding-top: 1rem;
}
.bag__total {
  display: flex;
  justify-content: space-between;
  font-family: var(--serif);
  font-size: 1.5rem;
  margin-bottom: 0.35rem;
}
.bag__ship {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ink-2);
}
.scrim {
  position: fixed;
  inset: 0;
  z-index: 85;
  background: rgba(22, 16, 12, 0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms var(--ease);
}
.scrim.is-on {
  opacity: 1;
  pointer-events: auto;
}

/* ---------- mobile ---------- */
@media (max-width: 900px) {
  .hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .hero__media {
    grid-column: 1;
    grid-row: 1;
    height: 46svh;
  }
  .hero__media::after {
    background: linear-gradient(0deg, var(--kiln) 0%, rgba(22, 16, 12, 0.2) 45%, transparent 75%);
  }
  .hero__text {
    grid-row: 2;
    padding: 0 var(--pad) clamp(2.5rem, 7vh, 4rem);
    margin-top: -3rem;
  }
  .fires__list {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
  .fire__btn {
    display: grid;
    grid-template-columns: 7.5rem 1fr;
    gap: 1rem;
    align-items: center;
  }
  .fire__media {
    aspect-ratio: 3 / 4;
  }
  .fire__body {
    margin-top: 0;
    padding-top: 0;
    border-top: 0;
    border-left: 2px solid var(--rule);
    padding-left: 1rem;
  }
  .shop__head {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
  .shelf__row {
    flex-wrap: wrap;
    align-items: flex-start;
  }
  .piece {
    flex-basis: calc(var(--w) / 275 * 100%);
    min-width: 8.5rem;
  }
  .care {
    grid-template-columns: 1fr;
  }
  .care__anno {
    position: static;
    max-width: none;
    margin-top: 0.75rem;
  }
  .care__annoline {
    display: none;
  }
  .notes,
  .foot {
    grid-template-columns: 1fr;
  }
  .ship__list {
    grid-template-columns: 1fr;
  }
  .firing__restock {
    grid-template-columns: 1fr;
  }
  .firing__readout {
    top: auto;
    bottom: clamp(1rem, 3vh, 2rem);
  }
  .firing__chart {
    max-height: 40vh;
  }
  .firing__beat:nth-child(2) {
    margin-left: 0;
  }
  .foot__credits div {
    grid-template-columns: 1fr;
    gap: 0.1rem;
  }
}

@media (max-width: 620px) {
  .top__nav {
    display: none;
  }
  .shop__filter {
    top: 3.1rem;
  }
  .note {
    grid-template-columns: 1fr;
  }
  .note__img {
    width: 6rem;
  }
  .piece {
    min-width: 7.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  [data-reveal] {
    opacity: 1;
    transform: none;
  }
}

